import numpy as np

def get_neighbors(grid, r, c, include_self=False):
    rows = len(grid)
    cols = len(grid[0])
    result = []
    if include_self:
        result.append((r, c))
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if 0 <= r+dr < rows and 0 <= c+dc < cols:
                if include_self and (dr == 0 and dc == 0):
                    continue
                result.append((r+dr, c+dc))
    return result

def get_3x3_region(grid, r, c):
    rows = len(grid)
    cols = len(grid[0])
    region = grid[max(0,r-1):min(r+2,rows)][max(0,c-1):min(c+2,cols)]
    return region

