# First, let's understand the structure better by looking at connected components of 8s
from collections import deque

def find_connected_components_of_8(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    components = []

    def bfs(start_pos):
        component = [start_pos]
        queue = deque([start_pos])
        visited.add(start_pos)
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if (nr, nc) not in visited and grid[nr][nc] == 8:
                        visited.add((nr, nc))
                        component.append((nr, nc))
                        queue.append((nr, nc))
        return component

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8 and (r, c) not in visited:
                comp = bfs((r, c))
                components.append(comp)
    return components

components = find_connected_components_of_8(demo_input)
print(f"Number of connected 8-components: {len(components)}")
for i, comp in enumerate(components[:10]):
    print(f"Component {i}: size={len(comp)}, positions={comp}")

# Check which component each 8->4 case belongs to
